package com.cyberencuentro.gamermode; import android.content.Intent; import android.os.Bundle; import android.widget.Button; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; class MainActivity : AppCompatActivity() { override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); val layout = android.widget.LinearLayout(this).apply { orientation = android.widget.LinearLayout.VERTICAL; setPadding(50,100,50,100); setBackgroundColor(android.graphics.Color.parseColor("#0F0F0F")) }; val title = TextView(this).apply { text = "CYBER ENCUENTRO\nGAMER MODE"; textSize = 28f; setTextColor(android.graphics.Color.parseColor("#39FF14")); gravity = android.view.Gravity.CENTER }; val status = TextView(this).apply { text = "Listo"; setTextColor(android.graphics.Color.WHITE); gravity = android.view.Gravity.CENTER; setPadding(0,40,0,40) }; val btn = Button(this).apply { text = "ACTIVAR MODO GAMER" }; btn.setOnClickListener { val intent = Intent(this, GamerModeService::class.java); startForegroundService(intent); status.text = "MODO GAMER ACTIVADO" }; layout.addView(title); layout.addView(status); layout.addView(btn); setContentView(layout) } }